package com.yeyamo_mobile.api.culture_service.domain;import static org.junit.jupiter.api.Assertions.*;import java.util.UUID;import org.junit.jupiter.api.Test;
class LanguageProgressTest{@Test void completionIsIdempotent(){LanguageProgress p=LanguageProgress.start("user","fr-CM",UUID.randomUUID());assertTrue(p.complete(80));assertFalse(p.complete(20));assertEquals(80,p.getScore());assertNotNull(p.getCompletedAt());}@Test void tracksAttemptsWithoutReplacingHistory(){LanguageProgress p=LanguageProgress.start("user","fr-CM",UUID.randomUUID());p.attempted();p.attempted();assertEquals(2,p.getAttemptCount());}}
